import{z as p,x as B,o as E,c as d,q as n,j as o,D as t,d as l,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"专家专精化分析","description":"","frontmatter":{"title":"专家专精化分析","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-specialization.md","filePath":"llm/expert-specialization.md","lastUpdated":1791413859000}'),A={name:"llm/expert-specialization.md"};function m(h,a,c,D,u,f){const r=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=n('<h1 id="专家专精化分析" tabindex="-1">专家专精化分析 <a class="header-anchor" href="#专家专精化分析" aria-label="Permalink to &quot;专家专精化分析&quot;">​</a></h1><div class="epigraph"><p>占用均匀只说明水位；专精化要看专家在数据类型、词类或任务上是否可分，以及关掉它是否可被其它专家顶上。</p><footer>—— 综合 Fedus et al., Switch Transformers, 2021 对专家行为的观察；Dai et al., DeepSeekMoE, 2024 对细粒度专家特化的讨论</footer></div><p><a href="/llm/sequence-level-balance">上一课</a>指出全局均匀会掩盖单序列扎堆，序列级均衡约束一条样本内的占用尖峰；过强会破坏短语级特化，短序列要缩放目标覆盖。缺口是那些均衡指标都不回答「专家 \\(i\\) 在干什么」：要用路由条件分布、探针与置零跌点，把专家当成功能槽。可学习门的切片要测才知道，与 <a href="/llm/hash-routing">哈希路由</a> 的人为切片不同。本课写专精化测量，不重写序列直方图的目标覆盖。后课微调与剪枝默认已经读完这条测量轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>序列级均衡回答的是一条样本内有没有占用尖峰。留下的是专家在干什么。可视化路由概率会得到一张热图，容易讲成故事。真正要的是可证伪的专精：在代码 vs 自然语言、标点 vs 实体、某种语言上，专家的接收分布是否显著偏离均匀；以及做因果干预——推理时禁止某专家，哪些任务掉点。缺口是把方法写进课序，避免 MoE 论文只报负载方差就声称「专家学会了分工」。</p><p><span class="marginnote">直觉类比：判断一位厨师是否真「专精川菜」，光看他做川菜次数多不算数（那只是热图）；还要看他做别的菜系少（条件分布）、蒙眼尝菜能猜出他是川菜师傅（探针）、不让他掌勺时川菜出品明显变差（干预）。三样都成立，才敢下「专精」的结论。</span></p><p>Switch 已经观察到部分专家 degeneracy。DeepSeekMoE 用更细的专家切分号称特化更清晰。本课不站队型号，只给测量轴。</p><p><span class="marginnote">专精化不是伦理上的「应该分工」。有的任务需要冗余专家抗抖动。测的是事实，剪不剪是下一课之后的工程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层，与头分析平行。第一，条件占用：\\(p(\\text{expert}\\mid\\text{域})\\) 与 \\(p(\\text{域}\\mid\\text{expert})\\)，域可以是语种、是否代码、token 频率桶。第二，专家输出探针：把专家 MLP 的激活对语言学标签做线性探针。第三，干预：将该专家的容量置零或替换成平均专家，测下游。三者一致才敢叫专精；只有热图不够。</p><p>比较应在相同均衡制度下进行。强序列级均匀会把专精冲淡，看起来「没有分工」，其实是正则禁止分工。报专精时要声明均衡配方。</p><h3 id="细粒度专家" tabindex="-1">细粒度专家 <a class="header-anchor" href="#细粒度专家" aria-label="Permalink to &quot;细粒度专家&quot;">​</a></h3><p>把一个宽 FFN 切成许多窄专家，同一「功能」可能摊到一组专家上。分析单位应允许<strong>专家组</strong>：聚类路由相关矩阵，再对簇做干预。否则会得出「单个窄专家无功能、整组有功能」的假矛盾。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可学习门在内容空间划 Voronoi。数据长尾使少数专家吃高频功能词，多数专家吃稀疏语义。均衡偏置把高频挤开，专精从「词频」转向更细的内容。节点受限则专精对齐设备。因此专精是路由机制的产物，不是专家 MLP 先天的。换哈希，专精轴变成哈希切片，探针会换故事。</p>',15)),(E(),o(s,null,{default:t(()=>[i(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22%E6%9D%A1%E4%BB%B6%E5%8D%A0%E7%94%A8%E6%98%BE%E8%91%97%E5%81%8F%E7%A6%BB%E5%9D%87%E5%8C%80%3F%22%5D%20--%3E%20G%7B%22%E4%B8%89%E5%B1%82%E8%AF%81%E6%8D%AE%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20E2%5B%22%E7%BA%BF%E6%80%A7%E6%8E%A2%E9%92%88%E5%8F%AF%E5%88%86%3F%22%5D%20--%3E%20G%0A%20%20E3%5B%22%E7%BD%AE%E9%9B%B6%E5%B9%B2%E9%A2%84%E8%B7%8C%E7%82%B9%E6%98%8E%E6%98%BE%3F%22%5D%20--%3E%20G%0A%20%20G%20--%3E%7C%22%E5%85%A8%E9%83%A8%E6%98%AF%22%7C%20SPEC%5B%22%E5%8F%AF%E5%A3%B0%E7%A7%B0%EF%BC%9A%E8%AF%A5%E4%B8%93%E5%AE%B6%E6%89%BF%E6%8B%85%E6%AD%A4%E5%8A%9F%E8%83%BD%22%5D%0A%20%20G%20--%3E%7C%22%E5%8F%AA%E6%9C%89%E7%83%AD%E5%9B%BE%22%7C%20NO%5B%22%E4%B8%8D%E5%8F%AF%E5%A3%B0%E7%A7%B0%E4%B8%93%E7%B2%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">常见误区：只凭路由热图就宣称「专家学会了分工」。热图颜色深可能只是该专家吃到了高频词（标点、常用字），与内容特化无关。可证伪的专精要条件分布、探针、干预三重证据齐全，缺任何一条都只是相关性故事。</span></p><p>冗余：若干专家路由相关接近 1，干预其中一个跌点小。这是剪枝候选。孤点：相关低且干预跌点大，是不可合并核心。后课剪枝合并按这张图动手。</p><p><span class="marginnote">训练早期专精不稳定，分析应在损失平稳后做。中途热图不能当最终电路。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>探针标签体系会引导叙事：只标语种就只看见语种专家。干预在 top-\\(k\\) 下会有其它专家顶上，跌点低估真实贡献，需要同时锁定量替代者。下一课微调会改变门，预训练上的专精图不能直接当指令模型的专精图。不要用本课给「MoE 一定可解释」背书。</p><p><span class="marginnote">为什么重要：top-\\(k\\) 路由下，禁用一个专家后其他专家会「顶班」，测出的跌点会低估它的真实贡献——就像主力下场替补补位，比分未必掉，但打法已经变了。严格测量要同时锁定量替代者，否则会误判「这个专家没用」而错剪。</span></p>',6)),(E(),o(s,null,{default:t(()=>[i(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%B7%AF%E7%94%B1%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20Cond%5B%22%E6%9D%A1%E4%BB%B6%E5%8D%A0%E7%94%A8%22%5D%0A%20%20R%20--%3E%20Corr%5B%22%E4%B8%93%E5%AE%B6%E7%9B%B8%E5%85%B3%E7%B0%87%22%5D%0A%20%20Corr%20--%3E%20Intv%5B%22%E7%BD%AE%E9%9B%B6%E5%B9%B2%E9%A2%84%22%5D%0A%20%20Cond%20--%3E%20Claim%5B%22%E4%B8%93%E7%B2%BE%E9%99%88%E8%BF%B0%22%5D%0A%20%20Intv%20--%3E%20Claim%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"专精化要条件分布加因果干预，不能只看负载均匀或路由热图。"),e("li",null,"均衡与节点约束会塑造专精轴；分析必须声明这些配方。"),e("li",null,"细粒度专家应按簇解释；冗余簇是剪枝候选，孤点不是。"),e("li",null,"专精随训练阶段与微调漂移。"),e("li",null,"出处：Fedus et al., 2021；Dai et al., 2024。")],-1))])}const x=p(A,[["render",m]]);export{F as __pageData,x as default};
